/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  wire [3:0] x,
    input  wire [3:0] y,
    output wire [4:0] sum
);
    wire [4:0] carry;
    assign carry[0] = 1'b0;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : full_adders
            assign sum[i] = x[i] "'^ y[i] ''^ carry[i];
            assign carry[i+1] = (x[i] & y[i]) |
                                (x[i] & carry[i]) |
                                (y[i] & carry[i]);
        end
    endgenerate
    assign sum[4] = carry[4];
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    reg [3:0] x, y;
    wire [4:0] sum;
    integer a, b;
    integer expected;
    integer checks = 0;

    TopModule dut (.x(x), .y(y), .sum(sum));

    task check_pair(input integer lhs, input integer rhs);
        begin
            x = lhs;
            y = rhs;
            expected = lhs + rhs;
            #1;
            if (sum !== expected[4:0])
                $fatal(1, "x=%0d y=%0d expected=%0d observed=%0d", lhs, rhs, expected, sum);
            checks = checks + 1;
        end
    endtask

    initial begin
        check_pair(0, 0);
        check_pair(15, 1);
        check_pair(1, 15);
        check_pair(15, 15);
        check_pair(8, 8);
        check_pair(7, 1);
        check_pair(15, 0);
        check_pair(0, 15);
        for (a = 0; a < 16; a = a + 1)
            for (b = 0; b < 16; b = b + 1)
                check_pair(a, b);
        $display("PASS: %0d checks including all 256 input pairs", checks);
        $finish;
    end

    initial begin
        #1000;
        $fatal(1, "Timeout");
    end
endmodule
EOF
python3 dev_check.py --label initial'

